#!/usr/bin/env python3
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]

def require(path):
    if not path.exists():
        raise SystemExit(f"STOP: required file not found: {path}")
    return path.read_text()

# 1. Add non-destructive export helpers to mockupLocalArchive.js.
local_path = ROOT / "src/lib/mockupLocalArchive.js"
local_text = require(local_path)
library_insert = "\nexport function localMockupGraphicExportSupported() {\n  return typeof window !== 'undefined'\n    && typeof window.showDirectoryPicker === 'function'\n    && Boolean(globalThis.crypto?.subtle);\n}\n\nfunction mockupGraphicExportReference(recordType, row, {\n  field = 'storage_path',\n  folder = 'Files',\n  fileName = '',\n  kind = 'file',\n} = {}) {\n  const path = row?.[field];\n  const preview = field === 'preview_storage_path';\n  const prepared = field === 'prepared_storage_path';\n  const bucket = preview\n    ? (row?.preview_storage_bucket || row?.storage_bucket)\n    : prepared\n      ? (row?.prepared_storage_bucket || row?.storage_bucket)\n      : row?.storage_bucket;\n  const provider = preview\n    ? (row?.preview_storage_provider || row?.storage_provider || 'supabase')\n    : prepared\n      ? (row?.prepared_storage_provider || row?.storage_provider || 'supabase')\n      : (row?.storage_provider || 'supabase');\n\n  if (!bucket || !path) return null;\n\n  return {\n    key: `${provider}:${bucket}/${path}`,\n    provider,\n    bucket,\n    path,\n    mime_type: preview ? 'image/webp' : (row?.mime_type || null),\n    folder,\n    file_name: fileName || path.split('/').pop() || 'asset',\n    kind,\n    references: [{ record_type: recordType, record_id: row.id, field }],\n  };\n}\n\nfunction mockupGraphicExportName(row, fallback) {\n  return row?.original_file_name\n    || row?.output_name\n    || row?.artwork_name\n    || row?.asset_name\n    || row?.file_name\n    || row?.packet_number\n    || fallback;\n}\n\nexport function buildMockupGraphicExportPlan(bundle, selections = {}) {\n  const options = {\n    blank_photos: selections.blank_photos !== false,\n    artwork_originals: selections.artwork_originals !== false,\n    artwork_prepared: selections.artwork_prepared !== false,\n    generated_mockups: selections.generated_mockups !== false,\n    production_files: selections.production_files !== false,\n    previews: Boolean(selections.previews),\n  };\n\n  const references = [];\n  const externalReferences = [];\n  const add = (reference) => {\n    if (reference) references.push(reference);\n  };\n  const external = (recordType, row, label) => {\n    if (!row?.source_url || row?.storage_path) return;\n    externalReferences.push({\n      record_type: recordType,\n      record_id: row.id,\n      label,\n      source_url: row.source_url,\n      reason: 'This asset is referenced by an external URL and is not stored in Mockup Studio cloud storage.',\n    });\n  };\n\n  if (options.blank_photos) {\n    (bundle?.blanks || []).forEach((row) => {\n      add(mockupGraphicExportReference('mockup_blank_assets', row, {\n        folder: 'Blank Photos',\n        fileName: mockupGraphicExportName(row, 'blank-photo'),\n        kind: 'blank_photo',\n      }));\n      external('mockup_blank_assets', row, mockupGraphicExportName(row, 'blank-photo'));\n    });\n  }\n\n  if (options.artwork_originals) {\n    (bundle?.artwork || []).forEach((row) => {\n      add(mockupGraphicExportReference('mockup_artwork_assets', row, {\n        folder: 'Artwork/Originals',\n        fileName: mockupGraphicExportName(row, 'artwork'),\n        kind: 'artwork_original',\n      }));\n      external('mockup_artwork_assets', row, mockupGraphicExportName(row, 'artwork'));\n    });\n  }\n\n  if (options.artwork_prepared) {\n    (bundle?.artwork || []).forEach((row) => {\n      add(mockupGraphicExportReference('mockup_artwork_assets', row, {\n        field: 'prepared_storage_path',\n        folder: 'Artwork/Prepared',\n        fileName: `${row?.artwork_name || row?.original_file_name || 'artwork'}-prepared`,\n        kind: 'artwork_prepared',\n      }));\n    });\n  }\n\n  if (options.generated_mockups) {\n    (bundle?.outputs || []).forEach((row) => {\n      add(mockupGraphicExportReference('mockup_outputs', row, {\n        folder: 'Mockups',\n        fileName: mockupGraphicExportName(row, 'mockup-output'),\n        kind: 'generated_mockup',\n      }));\n    });\n  }\n\n  if (options.production_files) {\n    (bundle?.packets || []).forEach((row) => {\n      add(mockupGraphicExportReference('mockup_production_packets', row, {\n        folder: 'Production',\n        fileName: mockupGraphicExportName(row, `production-${row?.id || 'file'}`),\n        kind: 'production_file',\n      }));\n    });\n  }\n\n  if (options.previews) {\n    [\n      ['mockup_blank_assets', bundle?.blanks || [], 'Previews/Blank Photos', 'blank_preview'],\n      ['mockup_artwork_assets', bundle?.artwork || [], 'Previews/Artwork', 'artwork_preview'],\n      ['mockup_outputs', bundle?.outputs || [], 'Previews/Mockups', 'mockup_preview'],\n      ['mockup_production_packets', bundle?.packets || [], 'Previews/Production', 'production_preview'],\n    ].forEach(([recordType, rows, folder, kind]) => {\n      rows.forEach((row) => {\n        add(mockupGraphicExportReference(recordType, row, {\n          field: 'preview_storage_path',\n          folder,\n          fileName: `${mockupGraphicExportName(row, 'preview')}-preview`,\n          kind,\n        }));\n      });\n    });\n  }\n\n  const unique = new Map();\n  references.forEach((row) => {\n    if (!unique.has(row.key)) unique.set(row.key, row);\n    else unique.get(row.key).references.push(...row.references);\n  });\n\n  return {\n    options,\n    references: [...unique.values()].sort((a, b) => (\n      `${a.folder}/${a.file_name}`.localeCompare(`${b.folder}/${b.file_name}`)\n    )),\n    external_references: externalReferences,\n  };\n}\n\nasync function nestedExportDirectory(root, folder) {\n  let current = root;\n  for (const part of String(folder || '').split('/').filter(Boolean)) {\n    current = await current.getDirectoryHandle(safeName(part, 'Files'), { create: true });\n  }\n  return current;\n}\n\nfunction reserveExportFileName(usedNames, folder, requestedName, sourcePath, mimeType) {\n  const extension = extensionFor(sourcePath, mimeType);\n  const requestedBase = String(requestedName || 'asset').replace(/\\.[a-z0-9]{1,8}$/i, '');\n  const base = safeName(requestedBase, 'asset');\n  const folderKey = String(folder || '');\n  if (!usedNames.has(folderKey)) usedNames.set(folderKey, new Set());\n  const used = usedNames.get(folderKey);\n\n  let candidate = `${base}${extension}`;\n  let suffix = 2;\n  while (used.has(candidate.toLowerCase())) {\n    candidate = `${base}-${suffix}${extension}`;\n    suffix += 1;\n  }\n  used.add(candidate.toLowerCase());\n  return candidate;\n}\n\nexport async function createLocalMockupGraphicExport({\n  project,\n  bundle,\n  selections = {},\n  onProgress = () => {},\n}) {\n  if (!localMockupGraphicExportSupported()) {\n    throw new Error('Downloading all Mockup Studio graphics requires Google Chrome or Microsoft Edge on this computer.');\n  }\n\n  const plan = buildMockupGraphicExportPlan(bundle, selections);\n  if (!plan.references.length) {\n    throw new Error('No stored Mockup Studio files match the selected download categories.');\n  }\n\n  const root = await window.showDirectoryPicker({ id: 'sc-mockup-graphics-downloads', mode: 'readwrite' });\n  if (!await ensurePermission(root)) throw new Error('Read and write access to the selected download folder was not granted.');\n\n  const stamp = new Date().toISOString().replace(/[:.]/g, '-');\n  const folderName = `${safeName(project?.project_name)}-graphics-${stamp}`;\n  const directory = await root.getDirectoryHandle(folderName, { create: true });\n  const usedNames = new Map();\n  const files = [];\n  let totalBytes = 0;\n\n  for (let index = 0; index < plan.references.length; index += 1) {\n    const reference = plan.references[index];\n    onProgress({\n      stage: 'download',\n      completed: index,\n      total: plan.references.length,\n      message: `Downloading project graphic ${index + 1} of ${plan.references.length}…`,\n    });\n\n    const blob = await downloadMockupStoredFile(reference);\n    if (!blob) throw new Error(`Could not download ${reference.path}: no file was returned.`);\n\n    const targetDirectory = await nestedExportDirectory(directory, reference.folder);\n    const localName = reserveExportFileName(\n      usedNames,\n      reference.folder,\n      reference.file_name,\n      reference.path,\n      reference.mime_type || blob.type,\n    );\n    const checksum = await sha256(blob);\n    const fileHandle = await writeFile(targetDirectory, localName, blob);\n    const savedFile = await fileHandle.getFile();\n\n    if (savedFile.size !== blob.size || await sha256(savedFile) !== checksum) {\n      throw new Error(`Local download verification failed for ${reference.path}. Cloud storage was not changed.`);\n    }\n\n    totalBytes += blob.size;\n    files.push({\n      kind: reference.kind,\n      local_file: `${reference.folder}/${localName}`,\n      source_key: reference.key,\n      size: blob.size,\n      sha256: checksum,\n      mime_type: reference.mime_type || blob.type || null,\n      references: reference.references,\n    });\n  }\n\n  const manifest = {\n    format: 'skilled-crafting-mockup-graphics-download',\n    export_version: 1,\n    project_id: project?.id || null,\n    project_name: project?.project_name || null,\n    created_at: new Date().toISOString(),\n    folder_hint: `${root.name}/${directory.name}`,\n    cloud_files_changed: false,\n    selections: plan.options,\n    file_count: files.length,\n    total_bytes: totalBytes,\n    files,\n    external_references_not_downloaded: plan.external_references,\n  };\n\n  await writeFile(directory, 'mockup-graphics-download-manifest.json', JSON.stringify(manifest, null, 2));\n  if (plan.external_references.length) {\n    await writeFile(\n      directory,\n      'external-references-not-downloaded.json',\n      JSON.stringify(plan.external_references, null, 2),\n    );\n  }\n\n  onProgress({\n    stage: 'complete',\n    completed: files.length,\n    total: files.length,\n    message: `${files.length} project file${files.length === 1 ? '' : 's'} downloaded and verified. Cloud storage was not changed.`,\n  });\n\n  return {\n    directory,\n    folder_name: directory.name,\n    folder_hint: manifest.folder_hint,\n    file_count: files.length,\n    total_bytes: totalBytes,\n    external_references_not_downloaded: plan.external_references.length,\n    manifest,\n  };\n}\n\n"
anchor = "export async function createLocalMockupArchive({ project, bundle, onProgress = () => {} }) {"
if "export async function createLocalMockupGraphicExport" not in local_text:
    if anchor not in local_text:
        raise SystemExit("STOP: could not locate createLocalMockupArchive in src/lib/mockupLocalArchive.js")
    local_text = local_text.replace(anchor, library_insert + "\n" + anchor, 1)
    local_path.write_text(local_text)
    print("Updated:", local_path)
else:
    print("Already installed:", local_path)

# 2. Add imports and UI panel to MockupStudio.jsx.
studio_path = ROOT / "src/MockupStudio.jsx"
studio_text = require(studio_path)

if "createLocalMockupGraphicExport," not in studio_text:
    import_anchor = "  createLocalMockupArchive,\n"
    if import_anchor not in studio_text:
        raise SystemExit("STOP: MockupStudio local archive import anchor was not found.")
    studio_text = studio_text.replace(
        import_anchor,
        "  createLocalMockupArchive,\n  createLocalMockupGraphicExport,\n",
        1,
    )

if "localMockupGraphicExportSupported," not in studio_text:
    support_anchor = "  localMockupArchiveSupported,\n"
    if support_anchor not in studio_text:
        raise SystemExit("STOP: MockupStudio local archive support import anchor was not found.")
    studio_text = studio_text.replace(
        support_anchor,
        "  localMockupArchiveSupported,\n  localMockupGraphicExportSupported,\n",
        1,
    )

component_insert = '\nfunction DownloadGraphicsPanel({ bundle, setBusy, setMessage }) {\n  const project = bundle.project;\n  const supported = localMockupGraphicExportSupported();\n  const [options, setOptions] = useState({\n    blank_photos: true,\n    artwork_originals: true,\n    artwork_prepared: true,\n    generated_mockups: true,\n    production_files: true,\n    previews: false,\n  });\n\n  const counts = {\n    blank_photos: (bundle.blanks || []).filter((row) => row.storage_path).length,\n    artwork_originals: (bundle.artwork || []).filter((row) => row.storage_path).length,\n    artwork_prepared: (bundle.artwork || []).filter((row) => row.prepared_storage_path).length,\n    generated_mockups: (bundle.outputs || []).filter((row) => row.storage_path).length,\n    production_files: (bundle.packets || []).filter((row) => row.storage_path).length,\n    previews: [...(bundle.blanks || []), ...(bundle.artwork || []), ...(bundle.outputs || []), ...(bundle.packets || [])]\n      .filter((row) => row.preview_storage_path).length,\n  };\n\n  const selectedCount = Object.entries(options)\n    .filter(([, enabled]) => enabled)\n    .reduce((total, [key]) => total + Number(counts[key] || 0), 0);\n\n  function toggle(key) {\n    setOptions((current) => ({ ...current, [key]: !current[key] }));\n  }\n\n  async function downloadAll() {\n    if (!selectedCount) {\n      setMessage(\'Choose at least one project-file category to download.\');\n      return;\n    }\n\n    setBusy(true);\n    try {\n      const result = await createLocalMockupGraphicExport({\n        project,\n        bundle,\n        selections: options,\n        onProgress: ({ message }) => setMessage(message),\n      });\n      setMessage(\n        `Downloaded and verified ${result.file_count} project file${result.file_count === 1 ? \'\' : \'s\'} `\n        + `to ${result.folder_hint}. Cloud/R2 files were not changed.`\n        + (result.external_references_not_downloaded\n          ? ` ${result.external_references_not_downloaded} external-only reference${result.external_references_not_downloaded === 1 ? \'\' : \'s\'} could not be copied directly; their URLs were saved in the download manifest.`\n          : \'\')\n      );\n    } catch (error) {\n      setMessage(`${error.message || \'Project graphic download failed.\'} Cloud storage was not changed.`);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <SectionCard\n      title="Download project graphics"\n      description="Make a non-destructive copy of this project\'s graphic files on your computer. Unlike Local Image Archive, this never deletes files from R2 or Supabase and does not change the project status."\n    >\n      {!supported ? (\n        <p className="mockup-archive-warning">Use Google Chrome or Microsoft Edge to choose a destination folder for bulk downloads.</p>\n      ) : null}\n\n      {project.status === \'archived\' ? (\n        <p className="mockup-archive-warning">This project is archived locally. Restore it to cloud storage first, or use the existing local archive folder.</p>\n      ) : (\n        <>\n          <div className="mockup-upload-queue">\n            <label className="mockup-check">\n              <input type="checkbox" checked={options.blank_photos} onChange={() => toggle(\'blank_photos\')} />\n              Blank photos ({counts.blank_photos})\n            </label>\n            <label className="mockup-check">\n              <input type="checkbox" checked={options.artwork_originals} onChange={() => toggle(\'artwork_originals\')} />\n              Original artwork ({counts.artwork_originals})\n            </label>\n            <label className="mockup-check">\n              <input type="checkbox" checked={options.artwork_prepared} onChange={() => toggle(\'artwork_prepared\')} />\n              Prepared artwork ({counts.artwork_prepared})\n            </label>\n            <label className="mockup-check">\n              <input type="checkbox" checked={options.generated_mockups} onChange={() => toggle(\'generated_mockups\')} />\n              Generated mockups ({counts.generated_mockups})\n            </label>\n            <label className="mockup-check">\n              <input type="checkbox" checked={options.production_files} onChange={() => toggle(\'production_files\')} />\n              Production files ({counts.production_files})\n            </label>\n            <label className="mockup-check">\n              <input type="checkbox" checked={options.previews} onChange={() => toggle(\'previews\')} />\n              Preview derivatives ({counts.previews}) — optional duplicate WebP previews\n            </label>\n          </div>\n\n          <p className="muted-text">\n            Files are organized into Blank Photos, Artwork, Mockups, Production, and optional Previews folders.\n            A JSON manifest with source references, sizes, and SHA-256 checksums is included.\n          </p>\n\n          <ActionButton tone="primary" onClick={downloadAll} disabled={!supported || !selectedCount}>\n            Download Project Graphics ({selectedCount})\n          </ActionButton>\n        </>\n      )}\n    </SectionCard>\n  );\n}\n\n'
component_anchor = "function LocalArchivePanel({ bundle, refresh, setBusy, setMessage }) {"
if "function DownloadGraphicsPanel" not in studio_text:
    if component_anchor not in studio_text:
        raise SystemExit("STOP: LocalArchivePanel anchor was not found.")
    studio_text = studio_text.replace(
        component_anchor,
        component_insert + "\n" + component_anchor,
        1,
    )

render_anchor = '          <StorageMigrationPanel bundle={bundle} refresh={() => loadProject()} setBusy={setBusy} setMessage={setMessage} />\n'
download_render = '          <DownloadGraphicsPanel bundle={bundle} setBusy={setBusy} setMessage={setMessage} />\n'
if download_render not in studio_text:
    if render_anchor not in studio_text:
        raise SystemExit("STOP: StorageMigrationPanel render anchor was not found.")
    studio_text = studio_text.replace(render_anchor, download_render + render_anchor, 1)

studio_path.write_text(studio_text)
print("Updated:", studio_path)

# 3. Version and test wiring.
package_path = ROOT / "package.json"
package = json.loads(require(package_path))
package["version"] = "1.4.21"
scripts = package.setdefault("scripts", {})
scripts["test:mockup-downloads"] = "node --test scripts/tests/mockup-download-all.test.mjs"
full_test = scripts.get("test", "")
needle = "npm run test:mockup-downloads"
if needle not in full_test:
    marker = "npm run test:mockups"
    if marker in full_test:
        full_test = full_test.replace(marker, marker + " && " + needle, 1)
    else:
        full_test = (full_test + " && " if full_test else "") + needle
scripts["test"] = full_test
package_path.write_text(json.dumps(package, indent=2) + "\n")
print("Updated:", package_path)

print()
print("Mockup Studio Download All Graphics v1.4.21 installed.")
print("No Supabase SQL migration is required.")
